   302  void MleRouter::SetStateRouter(uint16_t aRloc16)
   303  {
   304      ThreadNetif &netif = GetNetif();
   305
   306      SetRloc16(aRloc16);
   307
   308      SetRole(OT_DEVICE_ROLE_ROUTER);
   309      SetAttachState(kAttachStateIdle);
   310      mAttachCounter = 0;
   311      mAttachTimer.Stop();
   312      mMessageTransmissionTimer.Stop();
   313      mAdvertiseTimer.Stop();
   314      ResetAdvertiseInterval();
   315
   316      netif.SubscribeAllRoutersMulticast();
   317      mPreviousPartitionIdRouter = mLeaderData.GetPartitionId();
   318      netif.GetNetworkDataLeader().Stop();
   319      netif.GetIp6().SetForwardingEnabled(true);
   320      netif.GetIp6().GetMpl().SetTimerExpirations(kMplRouterDataMessageTimerExpirations);
   321      netif.GetMac().SetBeaconEnabled(true);
   322
   323      // remove children that do not have matching RLOC16
   324      for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValidOrRestoring); !iter.IsDone(); iter++)
   325      {
   326          if (GetRouterId(iter.GetChild()->GetRloc16()) != mRouterId)
   327          {
   328              RemoveNeighbor(*iter.GetChild());
   329          }
   330      }
   331  }
