   333  void MleRouter::SetStateLeader(uint16_t aRloc16)
   334  {
   335      ThreadNetif &netif = GetNetif();
   336
   337      SetRloc16(aRloc16);
   338
   339      SetRole(OT_DEVICE_ROLE_LEADER);
   340      SetAttachState(kAttachStateIdle);
   341      mAttachCounter = 0;
   342      mAttachTimer.Stop();
   343      mMessageTransmissionTimer.Stop();
   344      mAdvertiseTimer.Stop();
   345      ResetAdvertiseInterval();
   346      AddLeaderAloc();
   347
   348      netif.SubscribeAllRoutersMulticast();
   349      mPreviousPartitionIdRouter = mLeaderData.GetPartitionId();
   350      mStateUpdateTimer.Start(kStateUpdatePeriod);
   351
   352      netif.GetNetworkDataLeader().Start();
   353      netif.GetActiveDataset().StartLeader();
   354      netif.GetPendingDataset().StartLeader();
   355      netif.GetCoap().AddResource(mAddressSolicit);
   356      netif.GetCoap().AddResource(mAddressRelease);
   357      netif.GetIp6().SetForwardingEnabled(true);
   358      netif.GetIp6().GetMpl().SetTimerExpirations(kMplRouterDataMessageTimerExpirations);
   359      netif.GetMac().SetBeaconEnabled(true);
   360      netif.GetAddressResolver().Clear();
   361
   362      // remove children that do not have matching RLOC16
   363      for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValidOrRestoring); !iter.IsDone(); iter++)
   364      {
   365          if (GetRouterId(iter.GetChild()->GetRloc16()) != mRouterId)
   366          {
   367              RemoveNeighbor(*iter.GetChild());
   368          }
   369      }
   370
   371      otLogNoteMle("Leader partition id 0x%x", mLeaderData.GetPartitionId());
   372  }
