   399  void MleRouter::ResetAdvertiseInterval(void)
   400  {
   401      VerifyOrExit(mRole == OT_DEVICE_ROLE_ROUTER || mRole == OT_DEVICE_ROLE_LEADER);
   402
   403      if (!mAdvertiseTimer.IsRunning())
   404      {
   405          mAdvertiseTimer.Start(TimerMilli::SecToMsec(kAdvertiseIntervalMin),
   406                                TimerMilli::SecToMsec(kAdvertiseIntervalMax), TrickleTimer::kModeNormal);
   407      }
   408
   409      mAdvertiseTimer.IndicateInconsistent();
   410
   411  exit:
   412      return;
   413  }
