   682  otError MleRouter::SendLinkAccept(const Ip6::MessageInfo &aMessageInfo,
   683                                    Neighbor *              aNeighbor,
   684                                    const TlvRequestTlv &   aTlvRequest,
   685                                    const ChallengeTlv &    aChallenge)
   686  {
   687      otError                 error        = OT_ERROR_NONE;
   688      const otThreadLinkInfo *linkInfo     = static_cast<const otThreadLinkInfo *>(aMessageInfo.GetLinkInfo());
   689      static const uint8_t    routerTlvs[] = {Tlv::kLinkMargin};
   690      Message *               message;
   691      Header::Command         command;
   692      uint8_t                 linkMargin;
   693
   694      command = (aNeighbor == NULL || aNeighbor->GetState() == Neighbor::kStateValid)
   695                    ? Header::kCommandLinkAccept
   696                    : Header::kCommandLinkAcceptAndRequest;
   697
   698      VerifyOrExit((message = NewMleMessage()) != NULL, error = OT_ERROR_NO_BUFS);
   699      SuccessOrExit(error = AppendHeader(*message, command));
   700      SuccessOrExit(error = AppendVersion(*message));
   701      SuccessOrExit(error = AppendSourceAddress(*message));
   702      SuccessOrExit(error = AppendResponse(*message, aChallenge.GetChallenge(), aChallenge.GetLength()));
   703      SuccessOrExit(error = AppendLinkFrameCounter(*message));
   704      SuccessOrExit(error = AppendMleFrameCounter(*message));
   705
   706      // always append a link margin, regardless of whether or not it was requested
   707      linkMargin = LinkQualityInfo::ConvertRssToLinkMargin(GetNetif().GetMac().GetNoiseFloor(), linkInfo->mRss);
   708
   709      SuccessOrExit(error = AppendLinkMargin(*message, linkMargin));
   710
   711      if (aNeighbor != NULL && IsActiveRouter(aNeighbor->GetRloc16()))
   712      {
   713          SuccessOrExit(error = AppendLeaderData(*message));
   714      }
   715
   716      for (uint8_t i = 0; i < aTlvRequest.GetLength(); i++)
   717      {
   718          switch (aTlvRequest.GetTlvs()[i])
   719          {
   720          case Tlv::kRoute:
   721              SuccessOrExit(error = AppendRoute(*message));
   722              break;
   723
   724          case Tlv::kAddress16:
   725              VerifyOrExit(aNeighbor != NULL, error = OT_ERROR_DROP);
   726              SuccessOrExit(error = AppendAddress16(*message, aNeighbor->GetRloc16()));
   727              break;
   728
   729          case Tlv::kLinkMargin:
   730              break;
   731
   732          default:
   733              ExitNow(error = OT_ERROR_DROP);
   734          }
   735      }
   736
   737      if (aNeighbor != NULL && aNeighbor->GetState() != Neighbor::kStateValid)
   738      {
   739          aNeighbor->GenerateChallenge();
   740
   741          SuccessOrExit(error = AppendChallenge(*message, aNeighbor->GetChallenge(), aNeighbor->GetChallengeSize()));
   742          SuccessOrExit(error = AppendTlvRequest(*message, routerTlvs, sizeof(routerTlvs)));
   743          aNeighbor->SetLastHeard(TimerMilli::GetNow());
   744          aNeighbor->SetState(Neighbor::kStateLinkRequest);
   745      }
   746
   747  #if OPENTHREAD_CONFIG_ENABLE_TIME_SYNC
   748      if (aNeighbor->IsTimeSyncEnabled())
   749      {
   750          message->SetTimeSync(true);
   751      }
   752  #endif
   753
   754      if (aMessageInfo.GetSockAddr().IsMulticast())
   755      {
   756          SuccessOrExit(error = AddDelayedResponse(*message, aMessageInfo.GetPeerAddr(),
   757                                                   1 + Random::GetUint16InRange(0, kMaxResponseDelay)));
   758
   759          LogMleMessage("Delay Link Accept", aMessageInfo.GetPeerAddr());
   760      }
